import java.io.*;
import java.util.ArrayList;
import java.util.StringTokenizer;

public class B {
    public static void main(String[] args) throws Exception {
        java.io.BufferedReader br = new java.io.BufferedReader(new java.io.InputStreamReader(System.in));
        java.io.PrintWriter out = new java.io.PrintWriter(System.out);
        StringTokenizer st = new StringTokenizer(br.readLine());
        int maxX = Integer.parseInt(st.nextToken());
        double threshold = Double.parseDouble(st.nextToken());
        int answer = 0;
        for (int i = 0; i <= maxX; i++) {
            if (calculateFunction(maxX, i) >= threshold) {
                answer = i;
                break;
            }
        }
        out.print(answer);
        out.close();
    }

    public static double calculateFunction(int x, int n) {
        return -n * (n * n - 3 * n - 3 * x * x + 9 * x - 4) / (2 * (x - 2) * (x - 1) * x);
    }
}
